bool FastPlannerManager::planExploreTraj(const vector<Eigen::Vector3d>& tour,
    const Eigen::Vector3d& cur_vel, const Eigen::Vector3d& cur_acc, const double& time_lb) {
  invalidateExploreTraj();
  if (!cur_vel.allFinite() || !cur_acc.allFinite() || !std::isfinite(time_lb) ||
      !std::isfinite(pp_.max_vel_) || pp_.max_vel_ <= 0.0 ||
      !std::isfinite(pp_.ctrl_pt_dist) || pp_.ctrl_pt_dist <= 0.0 ||
      pp_.bspline_degree_ != 3 || bspline_optimizers_.empty()) {
    ROS_ERROR("Invalid exploration trajectory input or planner configuration.");
    return false;
  }
  vector<Eigen::Vector3d> filtered;
  for (const auto& point : tour) {
    if (!point.allFinite()) return false;
    if (filtered.empty() || (point - filtered.back()).norm() > 1e-5)
      filtered.push_back(point);
  }
  if (filtered.size() < 2) {
    ROS_WARN("Exploration path needs at least two distinct points.");
    return false;
  }
  // The upstream polynomial routine requires at least two segments.
  if (filtered.size() == 2)
    filtered.insert(filtered.begin() + 1, 0.5 * (filtered.front() + filtered.back()));

  const int pt_num = filtered.size();
  Eigen::MatrixXd pos(pt_num, 3);
  for (int i = 0; i < pt_num; ++i) pos.row(i) = filtered[i];
  Eigen::Vector3d zero(0, 0, 0);
  Eigen::VectorXd times(pt_num - 1);
  for (int i = 0; i < pt_num - 1; ++i) {
    times(i) = (filtered[i + 1] - filtered[i]).norm() / (pp_.max_vel_ * 0.5);
    if (!std::isfinite(times(i)) || times(i) <= 1e-6) return false;
  }
  const double initial_duration = times.sum();
  if (!std::isfinite(initial_duration) || initial_duration <= 1e-5)
    return false;

  PolynomialTraj init_traj;
  PolynomialTraj::waypointsTraj(pos, cur_vel, zero, cur_acc, zero, times, init_traj);
  const double duration = init_traj.getTotalTime();
  const double length = init_traj.getLength();
  if (!std::isfinite(duration) || duration <= 1e-5 || !std::isfinite(length) ||
      length <= 1e-5)
    return false;
  const int seg_num = max(8, static_cast<int>(length / pp_.ctrl_pt_dist));
  double dt = duration / static_cast<double>(seg_num);
  vector<Vector3d> points, boundary_deri;
  // Include both endpoints exactly, without a floating-step loop or overshoot.
  for (int i = 0; i <= seg_num; ++i) {
    const double t = i == seg_num ? duration : i * dt;
    const Vector3d point = init_traj.evaluate(t, 0);
    if (!point.allFinite()) return false;
    points.push_back(point);
  }
  boundary_deri.push_back(init_traj.evaluate(0.0, 1));
  boundary_deri.push_back(init_traj.evaluate(duration, 1));
  boundary_deri.push_back(init_traj.evaluate(0.0, 2));
  boundary_deri.push_back(init_traj.evaluate(duration, 2));
  for (const auto& derivative : boundary_deri)
    if (!derivative.allFinite()) return false;

  Eigen::MatrixXd ctrl_pts;
  NonUniformBspline::parameterizeToBspline(
      dt, points, boundary_deri, pp_.bspline_degree_, ctrl_pts);
  if (ctrl_pts.rows() < 6 || !ctrl_pts.allFinite()) return false;
  NonUniformBspline tmp_traj(ctrl_pts, pp_.bspline_degree_, dt);
  int cost_func = BsplineOptimizer::NORMAL_PHASE;
  if (pp_.min_time_) cost_func |= BsplineOptimizer::MINTIME;
  vector<Vector3d> start, end;
  tmp_traj.getBoundaryStates(2, 0, start, end);
  bspline_optimizers_[0]->setBoundaryStates(start, end);
  if (time_lb > 0) bspline_optimizers_[0]->setTimeLowerBound(time_lb);
  bspline_optimizers_[0]->optimize(ctrl_pts, dt, cost_func, 1, 1);
  if (!std::isfinite(dt) || dt <= 1e-6 || !ctrl_pts.allFinite()) return false;
  NonUniformBspline result(ctrl_pts, pp_.bspline_degree_, dt);
  if (!std::isfinite(result.getTimeSum()) || result.getTimeSum() <= 1e-5) return false;
  local_data_.position_traj_ = result;
  updateTrajInfo();
  return true;
}

void FastPlannerManager::invalidateExploreTraj() {
  local_data_.duration_ = 0.0;
  local_data_.start_pos_.setZero();
  local_data_.position_traj_ = NonUniformBspline();
  local_data_.velocity_traj_ = NonUniformBspline();
  local_data_.acceleration_traj_ = NonUniformBspline();
  local_data_.yaw_traj_ = NonUniformBspline();
  local_data_.yawdot_traj_ = NonUniformBspline();
  local_data_.yawdotdot_traj_ = NonUniformBspline();
}

